 for start,end in reg['source_triangle_index_ranges']:
  face_to_region[offsets[reg['object_index']]+start:offsets[reg['object_index']]+end+1]=region_index
counts={}
for image in images:
 frame=buffers[image['image_ref']]
 ids=frame['triangle_ids']; merged=np.full(ids.shape,-1,dtype=int); valid=ids>=0; merged[valid]=face_to_region[ids[valid]]
 rgb=frame['color'].astype(np.int32); boundary=np.zeros(ids.shape,dtype=bool)
 for axis in [0,1]:
  first=(slice(None,-1),slice(None)) if axis==0 else (slice(None),slice(None,-1))
  second=(slice(1,None),slice(None)) if axis==0 else (slice(None),slice(1,None))
  contrast=np.sum((rgb[first]-rgb[second])**2,axis=2)>=24**2
  qualifies=(merged[first]!=merged[second])&contrast
  boundary[first]|=qualifies; boundary[second]|=qualifies
 counts[image['view_name']]={idx:(int(np.count_nonzero(merged==idx)),int(np.count_nonzero((merged==idx)&boundary))) for idx in range(len(regions))}
for idx,reg in enumerate(regions):
 if reg['status']=='covered':
  witness=pixel_rows[reg['complete_witness_pixel_index']]; image=images[witness['image_index']]
  actual=counts[image['view_name']][idx]
  assert actual==(witness['visible_surface_pixels'],witness['contrasting_boundary_pixels']),(idx,actual,witness)
